CREATE OR REPLACE PROCEDURE
  `wfproc_import`(
)
BEGIN
  /*
   {"diagramJson": "{\"title\":\"Film scouting \\u00b7 score_locations (MCP tool)\",\"description\":\"Stage 2: score shortlisted areas (or a whole region) on logistics: state film incentives, airport access, hotels/tourism and healthcare, optionally blended with the stage-1 scenery score.\",\"nodes\":[{\"id\":\"s1\",\"data\":{\"id\":\"YOUR_PROJECT.YOUR_DATASET.film_scout_scoring\",\"name\":\"ReadTable\",\"type\":\"table\",\"label\":\"film_scout_scoring\",\"inputs\":[{\"name\":\"source\",\"type\":\"String\",\"title\":\"Source table\",\"value\":\"YOUR_PROJECT.YOUR_DATASET.film_scout_scoring\",\"description\":\"Read Table\"}]},\"type\":\"source\",\"position\":{\"x\":432,\"y\":0}},{\"id\":\"n2\",\"data\":{\"name\":\"native.where\",\"type\":\"generic\",\"label\":\"Where\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Filter expression\",\"value\":\"state IN UNNEST(SPLIT(UPPER(REPLACE(@region, ' ', '')), ',')) AND map_cells >= 10\",\"description\":\"Filter expression\",\"placeholder\":\"E.g.: area > 1000 AND area < 3000\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":608,\"y\":0}},{\"id\":\"n3\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"*, CASE LOWER(TRIM(@when)) WHEN 'fall' THEN [9, 10, 11] WHEN 'autumn' THEN [9, 10, 11] WHEN 'spring' THEN [3, 4, 5] WHEN 'summer' THEN [6, 7, 8] WHEN 'winter' THEN [12, 1, 2] ELSE [COALESCE(SAFE_CAST(@when AS INT64), CASE SUBSTR(LOWER(TRIM(@when)), 1, 3) WHEN 'jan' THEN 1 WHEN 'feb' THEN 2 WHEN 'mar' THEN 3 WHEN 'apr' THEN 4 WHEN 'may' THEN 5 WHEN 'jun' THEN 6 WHEN 'jul' THEN 7 WHEN 'aug' THEN 8 WHEN 'sep' THEN 9 WHEN 'oct' THEN 10 WHEN 'nov' THEN 11 WHEN 'dec' THEN 12 END, 10)] END AS shoot_months\",\"description\":\"SELECT statement\",\"placeholder\":\"E.g.: *, distance_in_km * 1000 AS distance_in_meters\",\"allowExpressions\":false}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":896,\"y\":0}},{\"id\":\"n4\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"*, (IF(1 IN UNNEST(shoot_months), jan_high_f, 0) + IF(2 IN UNNEST(shoot_months), feb_high_f, 0) + IF(3 IN UNNEST(shoot_months), mar_high_f, 0) + IF(4 IN UNNEST(shoot_months), apr_high_f, 0) + IF(5 IN UNNEST(shoot_months), may_high_f, 0) + IF(6 IN UNNEST(shoot_months), jun_high_f, 0) + IF(7 IN UNNEST(shoot_months), jul_high_f, 0) + IF(8 IN UNNEST(shoot_months), aug_high_f, 0) + IF(9 IN UNNEST(shoot_months), sep_high_f, 0) + IF(10 IN UNNEST(shoot_months), oct_high_f, 0) + IF(11 IN UNNEST(shoot_months), nov_high_f, 0) + IF(12 IN UNNEST(shoot_months), dec_high_f, 0)) / ARRAY_LENGTH(shoot_months) AS season_high_f, (IF(1 IN UNNEST(shoot_months), jan_low_f, 0) + IF(2 IN UNNEST(shoot_months), feb_low_f, 0) + IF(3 IN UNNEST(shoot_months), mar_low_f, 0) + IF(4 IN UNNEST(shoot_months), apr_low_f, 0) + IF(5 IN UNNEST(shoot_months), may_low_f, 0) + IF(6 IN UNNEST(shoot_months), jun_low_f, 0) + IF(7 IN UNNEST(shoot_months), jul_low_f, 0) + IF(8 IN UNNEST(shoot_months), aug_low_f, 0) + IF(9 IN UNNEST(shoot_months), sep_low_f, 0) + IF(10 IN UNNEST(shoot_months), oct_low_f, 0) + IF(11 IN UNNEST(shoot_months), nov_low_f, 0) + IF(12 IN UNNEST(shoot_months), dec_low_f, 0)) / ARRAY_LENGTH(shoot_months) AS season_low_f, (IF(1 IN UNNEST(shoot_months), jan_precip_in, 0) + IF(2 IN UNNEST(shoot_months), feb_precip_in, 0) + IF(3 IN UNNEST(shoot_months), mar_precip_in, 0) + IF(4 IN UNNEST(shoot_months), apr_precip_in, 0) + IF(5 IN UNNEST(shoot_months), may_precip_in, 0) + IF(6 IN UNNEST(shoot_months), jun_precip_in, 0) + IF(7 IN UNNEST(shoot_months), jul_precip_in, 0) + IF(8 IN UNNEST(shoot_months), aug_precip_in, 0) + IF(9 IN UNNEST(shoot_months), sep_precip_in, 0) + IF(10 IN UNNEST(shoot_months), oct_precip_in, 0) + IF(11 IN UNNEST(shoot_months), nov_precip_in, 0) + IF(12 IN UNNEST(shoot_months), dec_precip_in, 0)) / ARRAY_LENGTH(shoot_months) AS season_precip_in, (IF(1 IN UNNEST(shoot_months), jan_sun_mj, 0) + IF(2 IN UNNEST(shoot_months), feb_sun_mj, 0) + IF(3 IN UNNEST(shoot_months), mar_sun_mj, 0) + IF(4 IN UNNEST(shoot_months), apr_sun_mj, 0) + IF(5 IN UNNEST(shoot_months), may_sun_mj, 0) + IF(6 IN UNNEST(shoot_months), jun_sun_mj, 0) + IF(7 IN UNNEST(shoot_months), jul_sun_mj, 0) + IF(8 IN UNNEST(shoot_months), aug_sun_mj, 0) + IF(9 IN UNNEST(shoot_months), sep_sun_mj, 0) + IF(10 IN UNNEST(shoot_months), oct_sun_mj, 0) + IF(11 IN UNNEST(shoot_months), nov_sun_mj, 0) + IF(12 IN UNNEST(shoot_months), dec_sun_mj, 0)) / ARRAY_LENGTH(shoot_months) AS season_sun_mj\",\"description\":\"SELECT statement\",\"placeholder\":\"E.g.: *, distance_in_km * 1000 AS distance_in_meters\",\"allowExpressions\":false}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":1072,\"y\":0}},{\"id\":\"n5\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"*, (SELECT AVG(CASE t WHEN 'mountains' THEN match_mountains WHEN 'mountain' THEN match_mountains WHEN 'forest' THEN match_forest WHEN 'forests' THEN match_forest WHEN 'desert' THEN match_desert WHEN 'canyon' THEN match_canyon WHEN 'canyons' THEN match_canyon WHEN 'plains' THEN match_plains WHEN 'alpine' THEN match_alpine WHEN 'wetland' THEN match_wetland WHEN 'wetlands' THEN match_wetland END) FROM UNNEST(SPLIT(REPLACE(REPLACE(REPLACE(LOWER(@landscape), '+', ','), '&', ','), ' ', ''), ',')) AS t) AS landscape_match, CASE WHEN season_high_f BETWEEN 54 AND 82 THEN 1 WHEN season_high_f < 54 THEN LEAST(1, GREATEST(0, (season_high_f - 32) / 22)) ELSE LEAST(1, GREATEST(0, (100 - season_high_f) / 18)) END AS temp_score, LEAST(1, GREATEST(0, 1 - season_precip_in / 5.9)) AS dry_score, PERCENT_RANK() OVER (ORDER BY season_sun_mj) AS sun_score, LEAST(1, GREATEST(0, season_precip_in / 8)) AS wet_score, LEAST(1, GREATEST(0, (75 - season_high_f) / 25)) AS cool_score, LEAST(1, GREATEST(0, (45 - season_high_f) / 20)) AS cold_score, LEAST(1, GREATEST(0, (season_high_f - 80) / 20)) AS heat_score, LEAST(1, GREATEST(0, season_precip_in / 4)) AS snow_wet_score\",\"description\":\"SELECT statement\",\"placeholder\":\"E.g.: *, distance_in_km * 1000 AS distance_in_meters\",\"allowExpressions\":false}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":1360,\"y\":0}},{\"id\":\"n6\",\"data\":{\"name\":\"native.selectexpression\",\"type\":\"generic\",\"label\":\"Create Column\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"column\",\"type\":\"String\",\"title\":\"Name for new column\",\"value\":\"look_score\",\"validation\":\"^[a-zA-Z_][a-zA-Z0-9_]*$\",\"description\":\"Name for new column\",\"placeholder\":\"E.g.: distance_in_meters\",\"allowExpressions\":false},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Expression\",\"value\":\"landscape_match * (1 - LEAST(1, GREATEST(0, @w_weather))) + (CASE LOWER(TRIM(@weather)) WHEN 'rainy' THEN wet_score * 0.5 + (1 - sun_score) * 0.3 + cool_score * 0.2 WHEN 'foggy' THEN wet_score * 0.5 + (1 - sun_score) * 0.3 + cool_score * 0.2 WHEN 'gloomy' THEN wet_score * 0.5 + (1 - sun_score) * 0.3 + cool_score * 0.2 WHEN 'sunny' THEN sun_score * 0.5 + dry_score * 0.5 WHEN 'dry' THEN sun_score * 0.5 + dry_score * 0.5 WHEN 'snowy' THEN cold_score * 0.6 + snow_wet_score * 0.4 WHEN 'cold' THEN cold_score * 0.7 + cool_score * 0.3 WHEN 'hot' THEN heat_score * 0.7 + dry_score * 0.3 ELSE temp_score * 0.4 + dry_score * 0.35 + sun_score * 0.25 END) * LEAST(1, GREATEST(0, @w_weather))\",\"description\":\"Expression\",\"placeholder\":\"E.g.: distance_in_km * 1000\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":1536,\"y\":0}},{\"id\":\"n7\",\"data\":{\"name\":\"native.where\",\"type\":\"generic\",\"label\":\"Where\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Filter expression\",\"value\":\"(TRIM(@area_ids) = '' OR area_id IN UNNEST(SPLIT(REPLACE(@area_ids, ' ', ''), ','))) AND (@min_match <= 0 OR TRIM(@landscape) = '' OR landscape_match >= @min_match)\",\"description\":\"Filter expression\",\"placeholder\":\"E.g.: area > 1000 AND area < 3000\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":1824,\"y\":0}},{\"id\":\"n8\",\"data\":{\"name\":\"native.selectexpression\",\"type\":\"generic\",\"label\":\"Create Column\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"column\",\"type\":\"String\",\"title\":\"Name for new column\",\"value\":\"logistics_score\",\"validation\":\"^[a-zA-Z_][a-zA-Z0-9_]*$\",\"description\":\"Name for new column\",\"placeholder\":\"E.g.: distance_in_meters\",\"allowExpressions\":false},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Expression\",\"value\":\"(@w_incentives * incentive_score + @w_hotels * hotel_score + @w_healthcare * healthcare_score + @w_airport * airport_score) / NULLIF(@w_incentives + @w_hotels + @w_healthcare + @w_airport, 0)\",\"description\":\"Expression\",\"placeholder\":\"E.g.: distance_in_km * 1000\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":2112,\"y\":0}},{\"id\":\"n9\",\"data\":{\"name\":\"native.selectexpression\",\"type\":\"generic\",\"label\":\"Create Column\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"column\",\"type\":\"String\",\"title\":\"Name for new column\",\"value\":\"score\",\"validation\":\"^[a-zA-Z_][a-zA-Z0-9_]*$\",\"description\":\"Name for new column\",\"placeholder\":\"E.g.: distance_in_meters\",\"allowExpressions\":false},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Expression\",\"value\":\"CASE WHEN @w_scenery > 0 AND look_score IS NOT NULL THEN LEAST(1, GREATEST(0, @w_scenery)) * look_score + (1 - LEAST(1, GREATEST(0, @w_scenery))) * logistics_score ELSE logistics_score END\",\"description\":\"Expression\",\"placeholder\":\"E.g.: distance_in_km * 1000\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":2400,\"y\":0}},{\"id\":\"n10\",\"data\":{\"name\":\"native.selectexpression\",\"type\":\"generic\",\"label\":\"Create Column\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"column\",\"type\":\"String\",\"title\":\"Name for new column\",\"value\":\"rank\",\"validation\":\"^[a-zA-Z_][a-zA-Z0-9_]*$\",\"description\":\"Name for new column\",\"placeholder\":\"E.g.: distance_in_meters\",\"allowExpressions\":false},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Expression\",\"value\":\"ROW_NUMBER() OVER (ORDER BY score DESC)\",\"description\":\"Expression\",\"placeholder\":\"E.g.: distance_in_km * 1000\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":2576,\"y\":0}},{\"id\":\"n11\",\"data\":{\"name\":\"native.where\",\"type\":\"generic\",\"label\":\"Where\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"expression\",\"type\":\"StringSql\",\"title\":\"Filter expression\",\"value\":\"rank <= @top_n\",\"description\":\"Filter expression\",\"placeholder\":\"E.g.: area > 1000 AND area < 3000\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":2752,\"y\":0}},{\"id\":\"n12\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"rank, area_id, area_name, state, county, ROUND(score, 2) AS score, ROUND(logistics_score, 2) AS logistics_score, ROUND(look_score, 2) AS look_score, IF(@w_scenery > 0 AND look_score IS NOT NULL, LEAST(1, GREATEST(0, @w_scenery)), 0) AS scenery_weight, CASE WHEN rank <= 5 THEN '1 \\u00b7 Top 5' WHEN PERCENT_RANK() OVER (ORDER BY score) >= 0.75 THEN '2 \\u00b7 Top 25%' WHEN PERCENT_RANK() OVER (ORDER BY score) >= 0.5 THEN '3 \\u00b7 Upper middle' WHEN PERCENT_RANK() OVER (ORDER BY score) >= 0.25 THEN '4 \\u00b7 Lower middle' ELSE '5 \\u00b7 Bottom 25%' END AS score_tier, CAST(ROUND(IFNULL(score, 0) * 100) AS INT64) AS score_pct, IF(look_score IS NULL, NULL, CASE WHEN ROW_NUMBER() OVER (ORDER BY look_score DESC) <= 5 THEN '1 \\u00b7 Top 5' WHEN PERCENT_RANK() OVER (ORDER BY look_score) >= 0.75 THEN '2 \\u00b7 Top 25%' WHEN PERCENT_RANK() OVER (ORDER BY look_score) >= 0.5 THEN '3 \\u00b7 Upper middle' WHEN PERCENT_RANK() OVER (ORDER BY look_score) >= 0.25 THEN '4 \\u00b7 Lower middle' ELSE '5 \\u00b7 Bottom 25%' END) AS look_tier, IF(logistics_score IS NULL, NULL, CASE WHEN ROW_NUMBER() OVER (ORDER BY logistics_score DESC) <= 5 THEN '1 \\u00b7 Top 5' WHEN PERCENT_RANK() OVER (ORDER BY logistics_score) >= 0.75 THEN '2 \\u00b7 Top 25%' WHEN PERCENT_RANK() OVER (ORDER BY logistics_score) >= 0.5 THEN '3 \\u00b7 Upper middle' WHEN PERCENT_RANK() OVER (ORDER BY logistics_score) >= 0.25 THEN '4 \\u00b7 Lower middle' ELSE '5 \\u00b7 Bottom 25%' END) AS logistics_tier, ROUND(incentive_score, 2) AS incentive_score, ROUND(hotel_score, 2) AS hotel_score, ROUND(healthcare_score, 2) AS healthcare_score, ROUND(airport_score, 2) AS airport_score, incentive_pct, credit_base_pct, credit_uplift_pct, incentive_note, hotels_nearby, healthcare_nearby, nearest_hospital, ROUND(nearest_hospital_mi, 1) AS nearest_hospital_mi, nearest_airport, ROUND(nearest_airport_mi, 1) AS nearest_airport_mi, hotels_tourism_pois, healthcare_pois, restaurant_pois, population, lat, lon\",\"description\":\"SELECT statement\",\"placeholder\":\"E.g.: *, distance_in_km * 1000 AS distance_in_meters\",\"allowExpressions\":false}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":3040,\"y\":0}},{\"id\":\"n13\",\"data\":{\"name\":\"native.mcptooloutput\",\"type\":\"generic\",\"label\":\"MCP Tool Output\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"mode\":\"radio\",\"name\":\"mode\",\"type\":\"Selection\",\"title\":\"Output type\",\"value\":\"sync\",\"default\":\"async\",\"options\":[{\"icon\":\"sync\",\"name\":\"Sync\",\"value\":\"sync\",\"description\":\"Outputs a JSON object with the data and the FQN of the result when the tool is invoked.\"},{\"icon\":\"async\",\"name\":\"Async\",\"value\":\"async\",\"description\":\"When invoked, creates a job and outputs a JSON object with job metadata, including the result table FQN. The result is available once the job is complete.\"}],\"providers\":[\"bigquery\",\"snowflake\",\"databricksWarehouse\"],\"description\":\"Output type\",\"allowExpressions\":false},{\"name\":\"persistTable\",\"type\":\"Boolean\",\"title\":\"Persist table\",\"value\":true,\"showIf\":[{\"value\":\"sync\",\"parameter\":\"mode\"}],\"default\":false,\"providers\":[\"bigquery\",\"snowflake\",\"databricksWarehouse\"],\"description\":\"Save results to a table for later use (slightly slower but reusable)\",\"allowExpressions\":false}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":3216,\"y\":0}},{\"id\":\"note_overview\",\"data\":{\"name\":\"Note\",\"color\":\"#E5E5E5\",\"genAi\":false,\"label\":\"\",\"width\":360,\"height\":820,\"inputs\":[],\"markdown\":\"---\\nlabel: score_locations (MCP tool)\\n---\\n## score_locations\\n**Stage 2 tool the agent calls: the logistics.**\\n\\nPass the same `region`, `landscape`, `when`, `weather`, `w_weather` and `min_match` as stage 1 to score exactly the areas that matched (or give `area_ids`).\\n\\nWeights: `w_incentives`, `w_hotels`, `w_healthcare`, `w_airport`, plus `w_scenery` to blend in the stage-1 look score.\\n\\nReads `film_scout_scoring` (criterion scores are precomputed there by workflow 2). Published as an MCP tool.\",\"position\":{\"x\":0,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":0,\"y\":-300}},{\"id\":\"note_1\",\"data\":{\"name\":\"Note\",\"color\":\"#F6CF71\",\"genAi\":false,\"label\":\"\",\"width\":392,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 1. Region\\n---\\n**Where** keeps areas in the requested states with at least 10 res-6 cells.\",\"position\":{\"x\":408,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":408,\"y\":-300}},{\"id\":\"note_2\",\"data\":{\"name\":\"Note\",\"color\":\"#9EB9F3\",\"genAi\":false,\"label\":\"\",\"width\":392,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 2. Season climate\\n---\\nSame as stage 1: months for `when`, then seasonal averages.\",\"position\":{\"x\":872,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":872,\"y\":-300}},{\"id\":\"note_3\",\"data\":{\"name\":\"Note\",\"color\":\"#87C55F\",\"genAi\":false,\"label\":\"\",\"width\":392,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 3. Look score (same as stage 1)\\n---\\n- **Select** picks the landscape match and weather ingredients, as in stage 1.\\n- **Create Column**: `look_score`, matching what find_landscapes reported.\",\"position\":{\"x\":1336,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":1336,\"y\":-300}},{\"id\":\"note_4\",\"data\":{\"name\":\"Note\",\"color\":\"#FE88B1\",\"genAi\":false,\"label\":\"\",\"width\":216,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 4. Which areas\\n---\\n**Where** keeps the `area_ids` given, or the areas matching the look (`min_match`), or the whole region if neither is set.\",\"position\":{\"x\":1800,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":1800,\"y\":-300}},{\"id\":\"note_5\",\"data\":{\"name\":\"Note\",\"color\":\"#C9DB74\",\"genAi\":false,\"label\":\"\",\"width\":216,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 5. Logistics score\\n---\\n**Create Column**: weighted average of the precomputed `incentive_score`, `hotel_score`, `healthcare_score` and `airport_score`, using the four weights.\",\"position\":{\"x\":2088,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":2088,\"y\":-300}},{\"id\":\"note_6\",\"data\":{\"name\":\"Note\",\"color\":\"#8BE0A4\",\"genAi\":false,\"label\":\"\",\"width\":568,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 6. Blend and rank\\n---\\n- **Create Column**: score = `w_scenery` x look + (1 - `w_scenery`) x logistics.\\n- **Create Column** ranks; **Where** caps at `top_n`.\",\"position\":{\"x\":2376,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":2376,\"y\":-300}},{\"id\":\"note_7\",\"data\":{\"name\":\"Note\",\"color\":\"#B497E7\",\"genAi\":false,\"label\":\"\",\"width\":392,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 7. Output\\n---\\n- **Select** tidies the output, with sub-scores and three tiers for map styling: `score_tier` (final), `look_tier` and `logistics_tier`.\\n- **MCP Tool Output** returns rows and a saved table for the map.\",\"position\":{\"x\":3016,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":3016,\"y\":-300}}],\"edges\":[{\"id\":\"e1\",\"source\":\"s1\",\"target\":\"n2\",\"sourceHandle\":\"out\",\"targetHandle\":\"source\"},{\"id\":\"e2\",\"source\":\"n2\",\"target\":\"n3\",\"sourceHandle\":\"match\",\"targetHandle\":\"table\"},{\"id\":\"e3\",\"source\":\"n3\",\"target\":\"n4\",\"sourceHandle\":\"result\",\"targetHandle\":\"table\"},{\"id\":\"e4\",\"source\":\"n4\",\"target\":\"n5\",\"sourceHandle\":\"result\",\"targetHandle\":\"table\"},{\"id\":\"e5\",\"source\":\"n5\",\"target\":\"n6\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"},{\"id\":\"e6\",\"source\":\"n6\",\"target\":\"n7\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"},{\"id\":\"e7\",\"source\":\"n7\",\"target\":\"n8\",\"sourceHandle\":\"match\",\"targetHandle\":\"source\"},{\"id\":\"e8\",\"source\":\"n8\",\"target\":\"n9\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"},{\"id\":\"e9\",\"source\":\"n9\",\"target\":\"n10\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"},{\"id\":\"e10\",\"source\":\"n10\",\"target\":\"n11\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"},{\"id\":\"e11\",\"source\":\"n11\",\"target\":\"n12\",\"sourceHandle\":\"match\",\"targetHandle\":\"table\"},{\"id\":\"e12\",\"source\":\"n12\",\"target\":\"n13\",\"sourceHandle\":\"result\",\"targetHandle\":\"source\"}],\"variables\":[{\"name\":\"area_ids\",\"type\":\"String\",\"order\":1,\"value\":\"\",\"scopes\":[\"mcptool\"],\"helperText\":\"Comma-separated area_id values from find_landscapes; empty = whole region\",\"displayName\":\"Area IDs\"},{\"name\":\"region\",\"type\":\"String\",\"order\":2,\"value\":\"WA,OR,ID,MT,WY,CA,NV,UT,CO,AZ,NM\",\"scopes\":[\"mcptool\"],\"helperText\":\"Comma-separated state codes\",\"displayName\":\"Region (state codes)\"},{\"name\":\"w_incentives\",\"type\":\"Number\",\"order\":3,\"value\":\"1\",\"scopes\":[\"mcptool\"],\"helperText\":\"Relative weight\",\"displayName\":\"Weight: incentives\"},{\"name\":\"w_hotels\",\"type\":\"Number\",\"order\":4,\"value\":\"1\",\"scopes\":[\"mcptool\"],\"helperText\":\"Relative weight\",\"displayName\":\"Weight: hotels\"},{\"name\":\"w_healthcare\",\"type\":\"Number\",\"order\":5,\"value\":\"1\",\"scopes\":[\"mcptool\"],\"helperText\":\"Relative weight\",\"displayName\":\"Weight: healthcare\"},{\"name\":\"w_airport\",\"type\":\"Number\",\"order\":6,\"value\":\"1\",\"scopes\":[\"mcptool\"],\"helperText\":\"Relative weight\",\"displayName\":\"Weight: airport access\"},{\"name\":\"landscape\",\"type\":\"String\",\"order\":7,\"value\":\"\",\"scopes\":[\"mcptool\"],\"helperText\":\"Same landscape as stage 1; needed for w_scenery\",\"displayName\":\"Landscape (optional)\"},{\"name\":\"when\",\"type\":\"String\",\"order\":8,\"value\":\"fall\",\"scopes\":[\"mcptool\"],\"helperText\":\"Same season or month as stage 1\",\"displayName\":\"When (optional)\"},{\"name\":\"weather\",\"type\":\"String\",\"order\":9,\"value\":\"comfortable\",\"scopes\":[\"mcptool\"],\"helperText\":\"Same as stage 1\",\"displayName\":\"Weather mood (optional)\"},{\"name\":\"w_weather\",\"type\":\"Number\",\"order\":10,\"value\":\"0.3\",\"scopes\":[\"mcptool\"],\"helperText\":\"Same as stage 1\",\"displayName\":\"Weight: weather (optional)\"},{\"name\":\"w_scenery\",\"type\":\"Number\",\"order\":11,\"value\":\"0\",\"scopes\":[\"mcptool\"],\"helperText\":\"0 = logistics only, 1 = scenery only\",\"displayName\":\"Weight: scenery vs logistics\"},{\"name\":\"min_match\",\"type\":\"Number\",\"order\":12,\"value\":\"0\",\"scopes\":[\"mcptool\"],\"helperText\":\"With landscape: only score areas that match the look (same as stage 1)\",\"displayName\":\"Minimum landscape match\"},{\"name\":\"top_n\",\"type\":\"Number\",\"order\":13,\"value\":\"300\",\"scopes\":[\"mcptool\"],\"helperText\":\"How many areas to return\",\"displayName\":\"Max results\"}],\"procedure\":{},\"schedule\":{},\"viewport\":{\"x\":0,\"y\":0,\"zoom\":0.7},\"schemaVersion\":\"1.0.0\",\"connectionProvider\":\"bigquery\",\"useCache\":false,\"executionInfo\":{},\"mcpTool\":{\"draft\":{\"name\":\"score_locations\",\"inputs\":{\"when\":{\"description\":\"Optional. The same season or month used in find_landscapes (default fall).\"},\"top_n\":{\"description\":\"How many areas to return (default 300, so the whole matching set can be mapped). Use up to 300 with area_ids empty to map a scored grid of the whole region.\"},\"region\":{\"description\":\"Comma-separated US state codes. Common regions: Pacific Northwest = 'WA,OR,ID'; California = 'CA'; Southwest = 'AZ,NM,NV,UT'; Four Corners = 'AZ,NM,UT,CO'; Rockies = 'MT,WY,CO,ID,UT'; whole West = 'WA,OR,ID,MT,WY,CA,NV,UT,CO,AZ,NM'. Always applied; pass the same region used for find_landscapes.\"},\"weather\":{\"description\":\"Optional. The same weather mood used in find_landscapes (default comfortable).\"},\"area_ids\":{\"description\":\"Comma-separated area_id values from find_landscapes, e.g. '8428953ffffffff,84289c1ffffffff'. Leave empty ('') to score every area in region.\"},\"w_hotels\":{\"description\":\"Relative weight for hotels and tourism places within about an hour (default 1).\"},\"landscape\":{\"description\":\"Optional. The same landscape (type or comma-separated combination) used in find_landscapes. Required for w_scenery to have an effect.\"},\"min_match\":{\"description\":\"Optional, 0-1 (default 0 = no filter). With landscape: only score areas whose landscape match is at least this; use the same value as stage 1 to score the same set.\"},\"w_airport\":{\"description\":\"Relative weight for airport access: full points within 30 straight-line miles of the nearest airport, zero beyond 150 mi (90 mi, about 2 hours, scores 0.5). Default 1.\"},\"w_scenery\":{\"description\":\"Optional, 0-1 (default 0). Share of the final score that comes from scenery (stage-1 look_score: landscape match + weather); the rest is logistics. 'Scenery matters most' = 0.7, 'balanced' = 0.5, 'logistics first' = 0.3.\"},\"w_weather\":{\"description\":\"Optional. The same w_weather used in find_landscapes (default 0.3).\"},\"w_healthcare\":{\"description\":\"Relative weight for healthcare: half nearby healthcare capacity, half straight-line distance to the nearest hospital (full under 20 mi, zero beyond 60 mi). Default 1.\"},\"w_incentives\":{\"description\":\"Relative weight for film incentives (default 1). Use 0 to ignore, 2 to double.\"}},\"output\":{\"description\":\"One row per area; sort by rank. Three map-styling tiers, each 1 \\u00b7 Top 5 ... 5 \\u00b7 Bottom 25% among the returned rows: score_tier (final score; color the final layer by this), look_tier (look_score; null if no landscape given) and logistics_tier (logistics_score). score_pct (0-100). score (0-1: scenery_weight x look_score + (1 - scenery_weight) x logistics_score), logistics_score (weighted incentives, hotels, healthcare, airport), look_score (stage-1 scenery score, null if no landscape given), scenery_weight, incentive_score, hotel_score, healthcare_score, airport_score; incentive_pct = credit_base_pct + credit_uplift_pct and incentive_note (program summary; headline rates, check with the state film office); hotels_nearby and healthcare_nearby (CARTO Spatial Features POI counts in the area plus its 6 neighbors, about an hour's drive: tourism includes hotels and attractions, healthcare includes hospitals and clinics); nearest_hospital and nearest_hospital_mi, nearest_airport and nearest_airport_mi (straight-line miles from the area center; Overture places, name-filtered, so small airfields can appear); hotels_tourism_pois, healthcare_pois and restaurant_pois (counts inside the area only); population; area_name, state, county; lat, lon. area_id is an H3 resolution-4 cell index: map results with geoColumn h3:area_id.\"},\"description\":\"Stage 2 of film location scouting. Scores scouting AREAS on logistics: state film incentives (base rate plus location-based uplift), straight-line distance to the nearest airport, lodging and healthcare within about an hour (the area plus its 6 neighboring areas) and distance to the nearest hospital. Use AFTER find_landscapes: pass the same region, landscape, when, weather, w_weather and min_match (area_ids empty) to score exactly the areas stage 1 matched, or pass specific area_ids, or leave both empty to scan a whole region. Adjust weights to reflect what matters most. To trade scenery against logistics, pass the same landscape and when as stage 1 and set w_scenery (0 = logistics only, 0.5 = equal, 1 = scenery only).\"},\"name\":\"score_locations\",\"description\":\"Stage 2 of film location scouting. Scores scouting AREAS on logistics: state film incentives (base rate plus location-based uplift), straight-line distance to the nearest airport, lodging and healthcare within about an hour (the area plus its 6 neighboring areas) and distance to the nearest hospital. Use AFTER find_landscapes: pass the same region, landscape, when, weather, w_weather and min_match (area_ids empty) to score exactly the areas stage 1 matched, or pass specific area_ids, or leave both empty to scan a whole region. Adjust weights to reflect what matters most. To trade scenery against logistics, pass the same landscape and when as stage 1 and set w_scenery (0 = logistics only, 0.5 = equal, 1 = scenery only).\",\"enabled\":false},\"viewerMode\":{},\"executionSettings\":{\"cacheModes\":{\"api\":false,\"mcp\":false,\"editor\":false,\"viewer\":false}}}"}
